        "text": "ہجرت کا لغوی معنی چھوڑ دینا یا ترک کر دینا ہے۔ شرعی اصطلاح میں دین کی خاطر دار الکفر کو چھوڑ کر دار الاسلام کی طرف چلے جانا ہجرت کہلاتا ہے۔ تاریخِ اسلام میں ہجرتِ حبشہ اور ہجرتِ مدینہ تاریخ ساز سنگ میل ہیں۔ جہاد کے معنی انتہائی کوشش اور جدوجہد کے ہیں۔ اسلام میں جہاد فتنہ و فساد ختم کرنے اور دین کی سر بلندی کے لیے فرض کیا گیا ہے۔ جہاد کی اقسام میں جہاد بالنفس (نفس سے لڑائی)، جہاد بالمال اور جہاد بالسیف (مسلح جدوجہد) شامل ہیں۔ اسلام میں جہاد کے سخت اخلاقی اصول ہیں جن میں بوڑھوں، عورتوں، بچوں اور عبادت گاہوں پر حملے کی قطعی ممانعت ہے۔"
